rules.query:
// [IP-P4] Processus ayant contacté l'IP — Pivot / Adresse IP
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 60) * 1m; // défaut : 1h
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 60) * 1m; // défaut : 1h
let StartTime = T0 - Before;
let EndTime = T0 + After;

DeviceNetworkEvents
| where TimeGenerated between (StartTime .. EndTime)
| where RemoteIP == Value or LocalIP == Value
| extend Direction = iff(RemoteIP == Value, "Vers l'IP", "IP locale de la machine")
| sort by DeviceName asc, InitiatingProcessFileName asc, TimeGenerated asc
| extend GapSeconds = iff(DeviceName == prev(DeviceName) and InitiatingProcessFileName == prev(InitiatingProcessFileName),
    datetime_diff("second", TimeGenerated, prev(TimeGenerated)), long(null))
| summarize Connections = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
    MedianGapSeconds = percentile(GapSeconds, 50), Ports = make_set(RemotePort, 20), Urls = make_set(RemoteUrl, 10),
    Actions = make_set(ActionType), CommandLine = take_any(InitiatingProcessCommandLine)
    by DeviceName, Direction, Process = InitiatingProcessFileName, ProcessPath = InitiatingProcessFolderPath,
       Account = InitiatingProcessAccountName, ProcessSHA256 = InitiatingProcessSHA256
| sort by FirstSeen asc

