rules.query:
// [AC-S1] Connexions par application et par pays — Statistics / Compte
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 20160) * 1m; // défaut : 14d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Compte : accepte un UPN (user@domaine), DOMAINE\user ou un nom SAM.
// ValueUpn sert aux journaux Entra ID et Microsoft 365, ValueSam aux journaux Windows et Defender.
let ValueUpn = tolower(Value);
let ValueSam = tolower(tostring(split(tostring(split(ValueUpn, "@")[0]), @"\")[-1]));
// Connexions Entra ID interactives et non interactives, normalisées.
// Dans AADNonInteractiveUserSignInLogs, DeviceDetail, Status et LocationDetails sont des chaînes JSON :
// elles sont analysées pour obtenir les mêmes colonnes que SigninLogs.
// Paramètres : start, end, ip (vide = toutes), upn (vide = tous). Résultat : 0 = succès.
let _Signins = (start:datetime, end:datetime, ip:string, upn:string) {
    union isfuzzy=true
    (
        SigninLogs
        | where TimeGenerated between (start .. end)
        | where isempty(ip) or IPAddress == ip
        | where isempty(upn) or UserPrincipalName =~ upn
        | extend _dev = DeviceDetail, _loc = LocationDetails, _st = Status, SignInType = "Interactive"
    ),
    (
        AADNonInteractiveUserSignInLogs
        | where TimeGenerated between (start .. end)
        | where isempty(ip) or IPAddress == ip
        | where isempty(upn) or UserPrincipalName =~ upn
        | extend _dev = parse_json(DeviceDetail), _loc = parse_json(LocationDetails), _st = parse_json(Status), SignInType = "NonInteractive"
    )
    | extend
        DeviceName = tostring(_dev.displayName),
        DeviceId = tostring(_dev.deviceId),
        OperatingSystem = tostring(_dev.operatingSystem),
        Browser = tostring(_dev.browser),
        IsManaged = tostring(_dev.isManaged),
        IsCompliant = tostring(_dev.isCompliant),
        TrustType = tostring(_dev.trustType),
        City = tostring(_loc.city),
        FailureReason = tostring(_st.failureReason),
        Succeeded = ResultType == "0"
    | project TimeGenerated, SignInType, UserPrincipalName, UserId, AppDisplayName, AppId, ResourceDisplayName,
        ResultType, ResultDescription, FailureReason, Succeeded, IPAddress, Location, City, AutonomousSystemNumber,
        ClientAppUsed, UserAgent, DeviceName, DeviceId, OperatingSystem, Browser, IsManaged, IsCompliant, TrustType,
        ConditionalAccessStatus, AuthenticationRequirement, RiskLevelDuringSignIn, SessionId, CorrelationId
};
_Signins(StartTime, EndTime, "", ValueUpn)
| summarize SignIns = count(), Failures = countif(not(Succeeded)), ActiveDays = dcount(bin(TimeGenerated, 1d)),
    IPs = dcount(IPAddress), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated)
    by Country = Location, App = AppDisplayName
| extend NewCombination = FirstSeen > T0 - 2d
| sort by NewCombination desc, SignIns desc

// [AC-P1] IP et appareils utilisés par le compte — Pivot / Compte
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 1440) * 1m; // défaut : 24h
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 60) * 1m; // défaut : 1h
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Compte : accepte un UPN (user@domaine), DOMAINE\user ou un nom SAM.
// ValueUpn sert aux journaux Entra ID et Microsoft 365, ValueSam aux journaux Windows et Defender.
let ValueUpn = tolower(Value);
let ValueSam = tolower(tostring(split(tostring(split(ValueUpn, "@")[0]), @"\")[-1]));
// Connexions Entra ID interactives et non interactives, normalisées.
// Dans AADNonInteractiveUserSignInLogs, DeviceDetail, Status et LocationDetails sont des chaînes JSON :
// elles sont analysées pour obtenir les mêmes colonnes que SigninLogs.
// Paramètres : start, end, ip (vide = toutes), upn (vide = tous). Résultat : 0 = succès.
let _Signins = (start:datetime, end:datetime, ip:string, upn:string) {
    union isfuzzy=true
    (
        SigninLogs
        | where TimeGenerated between (start .. end)
        | where isempty(ip) or IPAddress == ip
        | where isempty(upn) or UserPrincipalName =~ upn
        | extend _dev = DeviceDetail, _loc = LocationDetails, _st = Status, SignInType = "Interactive"
    ),
    (
        AADNonInteractiveUserSignInLogs
        | where TimeGenerated between (start .. end)
        | where isempty(ip) or IPAddress == ip
        | where isempty(upn) or UserPrincipalName =~ upn
        | extend _dev = parse_json(DeviceDetail), _loc = parse_json(LocationDetails), _st = parse_json(Status), SignInType = "NonInteractive"
    )
    | extend
        DeviceName = tostring(_dev.displayName),
        DeviceId = tostring(_dev.deviceId),
        OperatingSystem = tostring(_dev.operatingSystem),
        Browser = tostring(_dev.browser),
        IsManaged = tostring(_dev.isManaged),
        IsCompliant = tostring(_dev.isCompliant),
        TrustType = tostring(_dev.trustType),
        City = tostring(_loc.city),
        FailureReason = tostring(_st.failureReason),
        Succeeded = ResultType == "0"
    | project TimeGenerated, SignInType, UserPrincipalName, UserId, AppDisplayName, AppId, ResourceDisplayName,
        ResultType, ResultDescription, FailureReason, Succeeded, IPAddress, Location, City, AutonomousSystemNumber,
        ClientAppUsed, UserAgent, DeviceName, DeviceId, OperatingSystem, Browser, IsManaged, IsCompliant, TrustType,
        ConditionalAccessStatus, AuthenticationRequirement, RiskLevelDuringSignIn, SessionId, CorrelationId
};
let Baseline = _Signins(StartTime - 30d, StartTime, "", ValueUpn)
    | summarize KnownIPs = make_set(IPAddress, 2000), KnownCountries = make_set(Location, 200),
        KnownAsn = make_set(AutonomousSystemNumber, 500), KnownDevices = make_set(DeviceId, 200)
    | extend JoinKey = 1;
_Signins(StartTime, EndTime, "", ValueUpn)
| summarize SignIns = count(), Successes = countif(Succeeded), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
    Apps = make_set(AppDisplayName, 10), ClientApps = make_set(ClientAppUsed, 5), UserAgents = make_set(UserAgent, 5)
    by IPAddress, Location, City, AutonomousSystemNumber, DeviceName, DeviceId, OperatingSystem, Browser, IsManaged, IsCompliant
| extend JoinKey = 1
| join kind=leftouter (Baseline) on JoinKey
| extend NewIP = not(set_has_element(KnownIPs, IPAddress)),
    NewCountry = not(set_has_element(KnownCountries, Location)),
    NewASN = not(set_has_element(KnownAsn, AutonomousSystemNumber)),
    UnknownDevice = isempty(DeviceId) or not(set_has_element(KnownDevices, DeviceId))
| project FirstSeen, LastSeen, IPAddress, NewIP, Location, NewCountry, City, AutonomousSystemNumber, NewASN,
    DeviceName, UnknownDevice, OperatingSystem, Browser, IsManaged, IsCompliant, SignIns, Successes, Apps, ClientApps, UserAgents
| sort by FirstSeen asc

// [AC-P3] Actions d'administration et de fichiers du compte — Pivot / Compte
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 240) * 1m; // défaut : 4h
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 240) * 1m; // défaut : 4h
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Compte : accepte un UPN (user@domaine), DOMAINE\user ou un nom SAM.
// ValueUpn sert aux journaux Entra ID et Microsoft 365, ValueSam aux journaux Windows et Defender.
let ValueUpn = tolower(Value);
let ValueSam = tolower(tostring(split(tostring(split(ValueUpn, "@")[0]), @"\")[-1]));
union isfuzzy=true
(
    AuditLogs
    | where TimeGenerated between (StartTime .. EndTime)
    | where InitiatedBy has ValueUpn or TargetResources has ValueUpn
    | project TimeGenerated, Source = "AuditLogs (Entra ID)", Operation = OperationName,
        Role = iff(tostring(InitiatedBy.user.userPrincipalName) =~ ValueUpn, "Auteur", "Cible"),
        Target = coalesce(tostring(TargetResources[0].userPrincipalName), tostring(TargetResources[0].displayName)),
        Result, IP = tostring(InitiatedBy.user.ipAddress)
),
(
    OfficeActivity
    | where TimeGenerated between (StartTime .. EndTime)
    | where UserId =~ ValueUpn
    | project TimeGenerated, Source = strcat("OfficeActivity (", OfficeWorkload, ")"), Operation, Role = "Auteur",
        Target = coalesce(OfficeObjectId, SourceFileName), Result = ResultStatus, IP = ClientIP
),
(
    CloudAppEvents
    | where TimeGenerated between (StartTime .. EndTime)
    | where tostring(RawEventData.UserId) =~ ValueUpn
    | project TimeGenerated, Source = strcat("CloudAppEvents (", Application, ")"), Operation = ActionType, Role = "Auteur",
        Target = ObjectName, Result = "", IP = IPAddress
),
(
    AzureActivity
    | where TimeGenerated between (StartTime .. EndTime)
    | where Caller =~ ValueUpn
    | project TimeGenerated, Source = "AzureActivity", Operation = OperationNameValue, Role = "Auteur",
        Target = _ResourceId, Result = ActivityStatusValue, IP = CallerIpAddress
)
| summarize Events = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
    Targets = make_set(Target, 10), IPs = make_set(IP, 5), Results = make_set(Result, 5) by Source, Operation, Role
| sort by Events desc

// [AC-P4] Règles de boîte, consentements et méthodes MFA — Pivot / Compte
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // défaut : 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Compte : accepte un UPN (user@domaine), DOMAINE\user ou un nom SAM.
// ValueUpn sert aux journaux Entra ID et Microsoft 365, ValueSam aux journaux Windows et Defender.
let ValueUpn = tolower(Value);
let ValueSam = tolower(tostring(split(tostring(split(ValueUpn, "@")[0]), @"\")[-1]));
let MailboxOps = dynamic(["New-InboxRule", "Set-InboxRule", "UpdateInboxRules", "Set-Mailbox", "Add-MailboxPermission",
    "Add-RecipientPermission", "Set-MailboxJunkEmailConfiguration", "New-TransportRule", "Set-TransportRule"]);
let EntraOps = dynamic(["Consent to application", "Add delegated permission grant", "Add app role assignment grant to user",
    "Add app role assignment to service principal", "Add service principal", "Add service principal credentials",
    "Add owner to application", "User registered security info", "User registered all required security info",
    "Admin registered security info", "User changed default security info", "Reset password (by admin)",
    "Change user password", "Add member to role", "Add eligible member to role"]);
let Flag = (text:string) {
    case(text has_any ("ForwardTo", "RedirectTo", "ForwardingSmtpAddress", "ForwardingAddress", "ForwardAsAttachmentTo"), "Transfert ou redirection",
        text has_any ("DeleteMessage", "MoveToFolder", "MarkAsRead", "SoftDeleteMessage"), "Suppression ou masquage",
        "")
};
union isfuzzy=true
(
    OfficeActivity
    | where TimeGenerated between (StartTime .. EndTime)
    | where Operation in (MailboxOps)
    | where UserId =~ ValueUpn or Parameters has ValueUpn
    | project TimeGenerated, Source = "OfficeActivity", Operation, Detail = substring(Parameters, 0, 1000), IP = ClientIP, Flag = Flag(Parameters)
),
(
    CloudAppEvents
    | where TimeGenerated between (StartTime .. EndTime)
    | where ActionType in (MailboxOps)
    | where tostring(RawEventData.UserId) =~ ValueUpn or RawEventData has ValueUpn
    | extend Params = tostring(RawEventData.Parameters)
    | project TimeGenerated, Source = "CloudAppEvents", Operation = ActionType, Detail = substring(Params, 0, 1000), IP = IPAddress, Flag = Flag(Params)
),
(
    AuditLogs
    | where TimeGenerated between (StartTime .. EndTime)
    | where OperationName in (EntraOps) or OperationName has "Certificates and secrets management"
    | where InitiatedBy has ValueUpn or TargetResources has ValueUpn
    | extend Changes = tostring(TargetResources[0].modifiedProperties)
    | project TimeGenerated, Source = "AuditLogs", Operation = OperationName,
        Detail = substring(strcat(tostring(TargetResources[0].displayName), " · ", Changes), 0, 1000),
        IP = tostring(InitiatedBy.user.ipAddress),
        Flag = case(OperationName has "Consent" or OperationName has "permission grant", "Consentement OAuth",
            OperationName has "security info", "Méthode d'authentification",
            OperationName has "password", "Mot de passe",
            OperationName has "role", "Rôle", "")
)
| sort by TimeGenerated asc

// [EM-S1] Volume de messages par jour et par verdict — Statistics / Adresse e-mail
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // défaut : 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Adresse e-mail.
let ValueMail = tolower(Value);
let ValueMailDomain = tostring(split(ValueMail, "@")[1]);
let ValueMailLocal = tostring(split(ValueMail, "@")[0]);
EmailEvents
| where TimeGenerated between (StartTime .. EndTime)
| where RecipientEmailAddress =~ ValueMail or SenderFromAddress =~ ValueMail or SenderMailFromAddress =~ ValueMail
| extend Role = iff(RecipientEmailAddress =~ ValueMail, "Reçu", "Envoyé"),
    Verdict = iff(isempty(ThreatTypes), DeliveryAction, strcat(DeliveryAction, " · ", ThreatTypes))
| summarize Mails = count() by bin(TimeGenerated, 1d), Serie = strcat(Role, " · ", Verdict)
| render timechart

