rules.query:
// [EM-S2] Prévalence de l'expéditeur — Statistics / Adresse e-mail
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // défaut : 30d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Adresse e-mail.
let ValueMail = tolower(Value);
let ValueMailDomain = tostring(split(ValueMail, "@")[1]);
let ValueMailLocal = tostring(split(ValueMail, "@")[0]);
EmailEvents
| where TimeGenerated between (StartTime .. EndTime)
| where SenderFromDomain =~ ValueMailDomain or SenderMailFromDomain =~ ValueMailDomain
| extend Scopes = iff(SenderFromAddress =~ ValueMail or SenderMailFromAddress =~ ValueMail,
    pack_array(strcat("Adresse ", ValueMail), strcat("Domaine ", ValueMailDomain)),
    pack_array(strcat("Domaine ", ValueMailDomain)))
| mv-expand Scope = Scopes to typeof(string)
| summarize FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated), Mails = count(),
    Recipients = dcount(RecipientEmailAddress), ActiveDays = dcount(bin(TimeGenerated, 1d)),
    Subjects = make_set(Subject, 10), SenderIPs = make_set(SenderIPv4, 10), Authentication = make_set(AuthenticationDetails, 5),
    Threats = make_set_if(ThreatTypes, isnotempty(ThreatTypes), 10), Directions = make_set(EmailDirection) by Scope
| extend NewInWindow = FirstSeen > T0 - 1d
| project Scope, NewInWindow, FirstSeen, LastSeen, Mails, Recipients, ActiveDays, Subjects, SenderIPs, Authentication, Threats, Directions

