rules.query:
// [AP-P1] Consentements, permissions et secrets de l'application — Pivot / Application
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // défaut : 30d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Application : AppId (GUID), identifiant de service principal ou nom affiché.
let ValueApp = Value;
let ValueAppLower = tolower(Value);
let Ops = dynamic(["Consent to application", "Add delegated permission grant", "Add app role assignment grant to user",
    "Add app role assignment to service principal", "Add service principal", "Add service principal credentials",
    "Add owner to application", "Add owner to service principal", "Update application", "Add application"]);
AuditLogs
| where TimeGenerated between (StartTime .. EndTime)
| where OperationName in (Ops) or OperationName has "Certificates and secrets management"
| where TargetResources has ValueApp or AdditionalDetails has ValueApp
| extend Changes = tostring(TargetResources[0].modifiedProperties)
| project TimeGenerated, OperationName, Result,
    Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName)),
    InitiatorIP = tostring(InitiatedBy.user.ipAddress),
    Target = tostring(TargetResources[0].displayName),
    ConsentType = extract(@"ConsentType: (\w+)", 1, Changes),
    IsAdminConsent = extract(@"IsAdminConsent[^A-Za-z]+(True|False)", 1, Changes),
    Scopes = extract_all(@"Scope: ([^,\]]+)", Changes),
    Changes = substring(Changes, 0, 1500)
| sort by TimeGenerated asc

// [AP-P2] Connexions et appels du service principal — Pivot / Application
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 10080) * 1m; // défaut : 7d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
// Indicateur Application : AppId (GUID), identifiant de service principal ou nom affiché.
let ValueApp = Value;
let ValueAppLower = tolower(Value);
union isfuzzy=true
(
    AADServicePrincipalSignInLogs
    | where TimeGenerated between (StartTime .. EndTime)
    | where AppId == ValueApp or ServicePrincipalId == ValueApp or ServicePrincipalName =~ ValueApp
    | project TimeGenerated, Source = "Service principal", Identity = ServicePrincipalName, IPAddress, Location,
        Operation = strcat("Connexion à ", ResourceDisplayName), Result = ResultType, Credential = ClientCredentialType
),
(
    AADManagedIdentitySignInLogs
    | where TimeGenerated between (StartTime .. EndTime)
    | where AppId == ValueApp or ServicePrincipalId == ValueApp or ServicePrincipalName =~ ValueApp
    | project TimeGenerated, Source = "Identité managée", Identity = ServicePrincipalName, IPAddress, Location,
        Operation = strcat("Connexion à ", ResourceDisplayName), Result = ResultType, Credential = "Identité managée"
),
(
    MicrosoftGraphActivityLogs
    | where TimeGenerated between (StartTime .. EndTime)
    | where AppId == ValueApp or ServicePrincipalId == ValueApp
    | project TimeGenerated, Source = "Microsoft Graph", Identity = coalesce(UserId, ServicePrincipalId), IPAddress, Location = "",
        Operation = strcat(RequestMethod, " ", replace_regex(tostring(parse_url(RequestUri).Path), @"[0-9a-fA-F-]{36}", "{id}")),
        Result = tostring(ResponseStatusCode), Credential = ""
)
| summarize Events = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated), IPs = make_set(IPAddress, 10),
    Locations = make_set(Location, 5), Results = make_set(Result, 5) by Source, Identity, Operation, Credential
| sort by Source asc, Events desc

// [HS-S1] Prévalence du hash — Statistics / Hash
// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}, {{HOST}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // défaut : 30d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
let HostFilter = tolower(tostring(split(trim(@"\s", iff(@"{{HOST}}" startswith "{{", "", @"{{HOST}}")), ".")[0]));
// Indicateur Hash : MD5 (32), SHA1 (40) ou SHA256 (64).
let ValueHash = tolower(Value);
let H = materialize(union isfuzzy=true
(
    union isfuzzy=true withsource=Source DeviceFileEvents, DeviceProcessEvents, DeviceImageLoadEvents, DeviceEvents
    | where TimeGenerated between (StartTime .. EndTime)
    | where SHA256 == ValueHash or SHA1 == ValueHash or MD5 == ValueHash
    | where isempty(HostFilter) or DeviceName startswith HostFilter
    | project TimeGenerated, Source, DeviceName = tolower(DeviceName), FileName, FolderPath
),
(
    EmailAttachmentInfo
    | where TimeGenerated between (StartTime .. EndTime)
    | where SHA256 == ValueHash
    | project TimeGenerated, Source = "EmailAttachmentInfo", DeviceName = tolower(RecipientEmailAddress), FileName, FolderPath = ""
));
union
(
    H
    | summarize Events = count(), Machines = dcount(DeviceName), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
        FileNames = make_set(FileName, 10), Paths = make_set(FolderPath, 10) by Source
),
(
    H
    | summarize Events = count(), Machines = dcount(DeviceName), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated),
        FileNames = make_set(FileName, 10), Paths = make_set(FolderPath, 10)
    | extend Source = "Total"
)
| project Source, Events, Machines, FirstSeen, LastSeen, FileNames, Paths
| sort by Source == "Total" desc, Events desc

