// sentinel-pivot-rules 0.1.0. Paramètres : {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}, {{HOST}}
let Value = trim(@"\s", @"{{VALUE}}");
let T0 = coalesce(todatetime(@"{{T0}}"), now());
let Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // défaut : 30d
let After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // défaut : 1d
let StartTime = T0 - Before;
let EndTime = T0 + After;
let HostFilter = tolower(tostring(split(trim(@"\s", iff(@"{{HOST}}" startswith "{{", "", @"{{HOST}}")), ".")[0]));
// Indicateur Hash : MD5 (32), SHA1 (40) ou SHA256 (64).
let ValueHash = tolower(Value);
union isfuzzy=true
(
    DeviceFileEvents
    | where Timestamp between (StartTime .. EndTime)
    | where SHA256 == ValueHash or SHA1 == ValueHash or MD5 == ValueHash
    | where isempty(HostFilter) or DeviceName startswith HostFilter
    | project Timestamp, DeviceName = tolower(DeviceName), FolderPath, FileName, Action = strcat("Fichier ", ActionType),
        Account = tolower(InitiatingProcessAccountName), Process = InitiatingProcessFileName
),
(
    DeviceProcessEvents
    | where Timestamp between (StartTime .. EndTime)
    | where SHA256 == ValueHash or SHA1 == ValueHash or MD5 == ValueHash
    | where isempty(HostFilter) or DeviceName startswith HostFilter
    | project Timestamp, DeviceName = tolower(DeviceName), FolderPath, FileName, Action = "Exécuté",
        Account = tolower(AccountName), Process = InitiatingProcessFileName
),
(
    DeviceImageLoadEvents
    | where Timestamp between (StartTime .. EndTime)
    | where SHA256 == ValueHash or SHA1 == ValueHash or MD5 == ValueHash
    | where isempty(HostFilter) or DeviceName startswith HostFilter
    | project Timestamp, DeviceName = tolower(DeviceName), FolderPath, FileName, Action = "Chargé (DLL)",
        Account = tolower(InitiatingProcessAccountName), Process = InitiatingProcessFileName
)
| summarize Events = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp), Actions = make_set(Action),
    Accounts = make_set(Account, 5), Processes = make_set(Process, 5) by DeviceName, FolderPath, FileName
| sort by FirstSeen asc

